mutation CreateSegmentDiscountCode($basicCodeDiscount: DiscountCodeBasicInput!) {
  discountCodeBasicCreate(basicCodeDiscount: $basicCodeDiscount) {
    codeDiscountNode {
      id
      codeDiscount {
        ... on DiscountCodeBasic {
          title
          codes(first: 10) {
            nodes {
              code
            }
          }
          context {
            ... on DiscountCustomerSegments {
              segments {
                id
              }
            }
          }
          customerGets {
            value {
              ... on DiscountAmount {
                amount {
                  amount
                  currencyCode
                }
                appliesOnEachItem
              }
            }
          }
        }
      }
    }
    userErrors {
      field
      message
    }
  }
}

mutation CreateDiscountCode($basicCodeDiscount: DiscountCodeBasicInput!) {
  discountCodeBasicCreate(basicCodeDiscount: $basicCodeDiscount) {
    codeDiscountNode {
      id
      codeDiscount {
        ... on DiscountCodeBasic {
          title
          startsAt
          endsAt
          customerSelection {
            ... on DiscountCustomers {
              customers {
                id
              }
            }
          }
          customerGets {
            value {
              ... on DiscountPercentage {
                percentage
              }
            }
          }
        }
      }
    }
    userErrors {
      field
      message
    }
  }
}

mutation CreateSummerDiscount($input: DiscountCodeBasicInput!) {
  discountCodeBasicCreate(basicCodeDiscount: $input) {
    codeDiscountNode {
      id
      codeDiscount {
        ... on DiscountCodeBasic {
          title
          codes(first: 10) {
            nodes {
              code
            }
          }
          startsAt
          endsAt
        }
      }
    }
    userErrors {
      field
      message
    }
  }
}

inputTypesSdl.DiscountAmountInput:
input DiscountAmountInput {
  amount: Decimal
  appliesOnEachItem: Boolean
}

inputTypesSdl.DiscountCombinesWithInput:
input DiscountCombinesWithInput {
  productDiscounts: Boolean
  orderDiscounts: Boolean
  shippingDiscounts: Boolean
}

inputTypesSdl.DiscountContextInput:
input DiscountContextInput {
  all: DiscountBuyerSelection
  customers: DiscountCustomersInput
  customerSegments: DiscountCustomerSegmentsInput
}

inputTypesSdl.DiscountCustomerGetsInput:
input DiscountCustomerGetsInput {
  value: DiscountCustomerGetsValueInput
  items: DiscountItemsInput
  appliesOnOneTimePurchase: Boolean
  appliesOnSubscription: Boolean
}

inputTypesSdl.DiscountCustomerGetsValueInput:
input DiscountCustomerGetsValueInput {
  discountOnQuantity: DiscountOnQuantityInput
  percentage: Float
  discountAmount: DiscountAmountInput
}

inputTypesSdl.DiscountEffectInput:
input DiscountEffectInput {
  percentage: Float
  amount: Decimal
}

inputTypesSdl.DiscountItemsInput:
input DiscountItemsInput {
  products: DiscountProductsInput
  collections: DiscountCollectionsInput
  all: Boolean
}

inputTypesSdl.DiscountMinimumRequirementInput:
input DiscountMinimumRequirementInput {
  quantity: DiscountMinimumQuantityInput
  subtotal: DiscountMinimumSubtotalInput
}

inputTypesSdl.DiscountOnQuantityInput:
input DiscountOnQuantityInput {
  quantity: UnsignedInt64
  effect: DiscountEffectInput
}

inputTypesSdl.DiscountProductsInput:
input DiscountProductsInput {
  productsToAdd: [ID!]
  productsToRemove: [ID!]
  productVariantsToAdd: [ID!]
  productVariantsToRemove: [ID!]
}
